rue, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'NON_BINDING', 'https://www.uob.edu.bh/launching-bittc-at-uob-under-the-patronage-of-the-minister-of-education/', '258', NULL, NULL) ON CONFLICT DO NOTHING;
