nt; Conferences and Workshops; Joint Projects; KPI Development', NULL, NULL, false, NULL, 'BHD', NULL, false, NULL, false, NULL, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'NON_BINDING', 'https://www.uob.edu.bh/34625/', '267', NULL, NULL) ON CONFLICT DO NOTHING;
