-AGR-270', NULL, 'INTERNATIONAL', '2023-06-20', '2028-06-19', NULL, NULL, false, NULL, NULL, 6, NULL, NULL, NULL, NULL, 'High-Energy Physics; Scientific and Technical Cooperation; Research Collaboration; CMS Experiment; STEM Training; Accelerator and Detector Engineering; Computing; Materials Research', NULL, NULL, false, NULL, 'BHD', NULL, false, NULL, false, NULL, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'NON_BINDING', 'https://www.uob.edu.bh/35571/', '270', NULL, NULL) ON CONFLICT DO NOTHING;
