udent Exchange; International Academic Cooperation', NULL, NULL, false, NULL, 'BHD', NULL, false, NULL, false, NULL, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'NON_BINDING', 'https://www.uob.edu.bh/39051/', '271', NULL, NULL) ON CONFLICT DO NOTHING;
