OB-AGR-272', NULL, 'INTERNATIONAL', '2023-09-18', '2026-09-17', NULL, NULL, false, NULL, NULL, 6, NULL, NULL, NULL, NULL, 'Accounting Education; Professional Qualifications; Student Employability; Faculty Development; Professional Development; Research and Insights', NULL, NULL, false, NULL, 'BHD', NULL, false, NULL, false, NULL, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'NON_BINDING', 'https://www.uob.edu.bh/38013/', '272', NULL, NULL) ON CONFLICT DO NOTHING;
