, false, NULL, NULL, 6, 4, NULL, NULL, NULL, 'Cybersecurity; Awareness Programmes; Student Training; Faculty Development; National Capacity Building; Scientific Research; Academic-Industry-Government Partnerships', NULL, NULL, false, NULL, 'BHD', NULL, false, NULL, false, NULL, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'NON_BINDING', 'https://www.uob.edu.bh/%D8%A7%D9%84%D9%85%D8%B1%D9%83%D8%B2-%D8%A7%D9%84%D9%88%D8%B7%D9%86%D9%8A-%D9%84%D9%84%D8%A3%D9%85%D9%86-%D8%A7%D9%84%D8%B3%D9%8A%D8%A8%D8%B1%D8%A7%D9%86%D9%8A-%D9%88%D8%AC%D8%A7%D9%85%D8%B9%D8%A9/?lang=ar', '277', NULL, NULL) ON CONFLICT DO NOTHING;
