, 'BHD', NULL, false, NULL, false, NULL, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'NON_BINDING', 'https://www.uob.edu.bh/the-university-of-bahrain-and-the-arab-open-university-sign-a-memorandum-of-cooperation-in-academic-fields-exchanging-experiences-and-promoting-scientific-research/', '278', NULL, NULL) ON CONFLICT DO NOTHING;
