 NULL, NULL, false, NULL, 'BHD', NULL, false, NULL, false, NULL, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'NON_BINDING', 'https://www.uob.edu.bh/uob-signs-mou-with-imam-malik-college-of-sharia-and-law-in-the-uae/', '291', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.agreements (agreement_id, title, description, agreement_type, status, created_by, created_at, updated_at, agreement_code, title_ar, geographic_scope, start_date, end_date, effective_date, signing_date, auto_renew, renewal_term_months, non_renewal_notice_months, termination_notice_months, responsible_unit_id, need_justification, expected_value, objectives, focus_areas, collaboration_areas, implementation_methods, financial_commitments, financial_amount, financial_currency, financial_description, human_resources_commitments, human_resources_description, training_programs, training_programs_description, annual_report_required, monitoring_plan, confidentiality_terms, intellectual_property_terms, compliance_terms, relationship_disclaimer, amendment_terms, dispute_resolution_terms, other_terms, legal_binding_status, signing_link, source_record_id, activated_at, expired_at) OVERRIDING SYSTEM VALUE VALUES (147, 'MOU - Technical University of Crete', 'MOU between the University of Bahrain and the Technical University of Crete to establish a framework for future academic collaboration benefiting students and faculty. Key provisions include cooperation through academic programs in instruction, research and faculty development; enhancing international experience through research, joint programs and collaboration; exchange of faculty and students; identifying concrete areas of academic collaboration; and coordinating future program details through later formal arrangements.', 'Memorandum of Understanding / MOU', 'ACTIVE', 1, '2026-05-10 17:02:39', '2026-07-26 16:57:20.16977', 'UOB-AGR-292', NULL, 'INTERNATIONAL', '2025-04-10', '2030-04-09', NULL, NULL, false, NULL, NULL, 6, NULL, NULL, NULL, NULL, 'Academic Collaboration; Research Collaboration; Faculty Development; Joint Programs; Faculty and Student Exchange; International Cooperation', NULL, NULL, false, NULL, 'BHD', NULL, false, NULL, false, NULL, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'NON_BINDING', NULL, '292', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.agreements (agreement_id, title, description, agreement_type, status, created_by, created_at, updated_at, agreement_code, title_ar, geographic_scope, start_date, end_date, effective_date, signing_date, auto_renew, renewal_term_months, non_renewal_notice_months, termination_notice_months, responsible_unit_id, need_justification, expected_value, objectives, focus_areas, collaboration_areas, implementation_methods, financial_commitments, financial_amount, financial_currency, financial_description, human_resources_commitments, human_resources_description, training_programs, training_programs_description, annual_report_required, monitoring_plan, confidentiality_terms, intellectual_property_terms, compliance_terms, relationship_disclaimer, amendment_terms, dispute_resolution_terms, other_terms, legal_binding_status, signing_link, source_record_id, activated_at, expired_at) OVERRIDING SYSTEM VALUE VALUES (149, 'MOU - You and Kim Consulting Company and Technology Engineering', 'MOU between the University of Bahrain, You and Kim Consulting Company, and Technology Engineering to jointly establish and operate a startup Research and Training Laboratory for Solar Energy and Information Technologies at UoB. Key provisions include training in solar design, feasibility studies, financing, marketing, management, operations and maintenance, information technologies and smart farm technologies; providing laboratory space, administration and trainee students; providing online courses, manuals, visual training content, onsite solar project training, outreach and networking with Korean technologies and companies; and supporting trainees’ engagement in solar energy and information technology projects.', 'Memorandum of Understanding / MOU', 'ACTIVE', 1, '2026-05-10 17:02:39', '2026-07-26 16:57:20.16977', 'UOB-AGR-295', NULL, 'LOCAL', '2025-10-09', '2028-10-09', NULL, NULL, false, NULL, NULL, 6, NULL, NULL, NULL, NULL, 'Solar Energy; Renewable Energy; Information Technology; Smart Farm Technologies; Training; Research and Development; Industry Collaboration; Korean Technology Collaboration', NULL, NULL, false, NULL, 'BHD', NULL, false, NULL, false, NULL, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'NON_BINDING', 'https://www.uob.edu.bh/wp-content/uploads/2026/04/Annual-Report-2025.pdf', '295', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.agreements (agreement_id, title, description, agreement_type, status, created_by, created_at, updated_at, agreement_code, title_ar, geographic_scope, start_date, end_date, effective_date, signing_date, auto_renew, renewal_term_months, non_renewal_notice_months, termination_notice_months, responsible_unit_id, need_justification, expected_value, objectives, focus_areas, collaboration_areas, implementation_methods, financial_commitments, financial_amount, financial_currency, financial_description, human_resources_commitments, human_resources_description, training_programs, training_programs_description, annual_report_required, monitoring_plan, confidentiality_terms, intellectual_property_terms, compliance_terms, relationship_disclaimer, amendment_terms, dispute_resolution_terms, other_terms, legal_binding_status, signing_link, source_record_id, activated_at, expired_at) OVERRIDING SYSTEM VALUE VALUES (150, 'MOU - Incheon National University (INU)', 'MOU between the University of Bahrain and Incheon National University to support mutually beneficial educational, cultural and research exchange. Key provisions include exchange of faculty, students, staff and researchers; joint development of study programmes at all levels; joint research activities; exchange of academic materials, publications and other information; and other activities by mutual consent. Specific visits, exchanges and cooperation arrangements are to be negotiated separately and depend on available financial and human resources.', 'Memorandum of Understanding / MOU', 'ACTIVE', 1, '2026-05-10 17:02:39', '2026-07-26 16:57:20.16977', 'UOB-AGR-296', NULL, 'INTERNATIONAL', '2025-12-04', '2028-12-04', NULL, NULL, false, NULL, NULL, 6, NULL, NULL, NULL, NULL, 'Academic Collaboration; Educational Exchange; Cultural Exchange; Research Collaboration; Faculty and Student Exchange; Joint Programmes; Academic Materials Exchange', NULL, NULL, false, NULL, 'BHD', NULL, false, NULL, false, NULL, true, 