INSERT INTO public.agreements (agreement_id, title, description, agreement_type, status, created_by, created_at, updated_at, agreement_code, title_ar, geographic_scope, start_date, end_date, effective_date, signing_date, auto_renew, renewal_term_months, non_renewal_notice_months, termination_notice_months, responsible_unit_id, need_justification, expected_value, objectives, focus_areas, collaboration_areas, implementation_methods, financial_commitments, financial_amount, financial_currency, financial_description, human_resources_commitments, human_resources_description, training_programs, training_programs_description, annual_report_required, monitoring_plan, confidentiality_terms, intellectual_property_terms, compliance_terms, relationship_disclaimer, amendment_terms, dispute_resolution_terms, other_terms, legal_binding_status, signing_link, source_record_id, activated_at, expired_at) OVERRIDING SYSTEM VALUE VALUES (151, 'MOU - Universiti Sains Malaysia', 'MOU between Universiti Sains Malaysia (USM) and the University of Bahrain to establish an academic link and cooperation framework for research, education and training programmes. Key provisions include exchanging professors, lecturers and researchers; cooperation in MA and PhD examination and supervision; joint research projects and studies; joint publications in accredited international journals; online or face-to-face seminars, workshops, conferences and exhibitions; exchange of technical information on international university rankings; organized student visits; participation in events and programmes; forming a joint committee; and holding at least one annual meeting to assess implementation and suggest new areas of partnership.', 'Memorandum of Understanding / MOU', 'ACTIVE', 1, '2026-05-10 17:02:39', '2026-07-26 16:57:20.16977', 'UOB-AGR-297', NULL, 'INTERNATIONAL', '2025-05-27', '2030-05-27', NULL, NULL, false, NULL, NULL, 6, 3, NULL, NULL, NULL, 'Academic Collaboration; Research Collaboration; Education and Training Programmes; Faculty and Researcher Exchange; Joint Publications; University Rankings Information Exchange', NULL, NULL, false, NULL, 'BHD', NULL, false, NULL, false, NULL, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'NON_BINDING', 'https://www.uob.edu.bh/during-hrh-the-crown-prince-and-prime-ministers-official-visit-to-malaysia-uob-signs-mou-with-usm/', '297', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.agreements (agreement_id, title, description, agreement_type, status, created_by, created_at, updated_at, agreement_code, title_ar, geographic_scope, start_date, end_date, effective_date, signing_date, auto_renew, renewal_term_months, non_renewal_notice_months, termination_notice_months, responsible_unit_id, need_justification, expected_value, objectives, focus_areas, collaboration_areas, implementation_methods, financial_commitments, financial_amount, financial_currency, financial_description, human_resources_commitments, human_resources_description, training_programs, training_programs_description, annual_report_required, monitoring_plan, confidentiality_terms, intellectual_property_terms, compliance_terms, relationship_disclaimer, amendment_terms, dispute_resolution_terms, other_terms, legal_binding_status, signing_link, source_record_id, activated_at, expired_at) OVERRIDING SYSTEM VALUE VALUES (152, 'Cooperation Agreement - Confucius Institute + Abdul Rahman Kanoo School Diyar', 'Cooperation Agreement and Memorandum of Cooperation between the University of Bahrain, Confucius Institute at UOB, and Abdul Rahman Kanoo School Diyar to support Chinese language teaching and related cultural activities at ARKS Diyar. Key provisions include dispatching a full-time Chinese teacher upon request; teaching from Reception to Grade 9 and related organizational tasks; providing replacement teachers if needed; following an ARKS-approved curriculum tailored to students’ needs; evaluation of Chinese language teaching and education; other academic exchange and cooperation programmes approved by the parties; signing specific project agreements before implementation; and maintaining confidentiality and intellectual property terms.', 'Cooperation Agreement', 'ACTIVE', 1, '2026-05-10 17:02:39', '2026-07-26 16:57:20.16977', 'UOB-AGR-298', NULL, 'LOCAL', '2025-10-15', '2026-10-15', NULL, NULL, false, NULL, NULL, 6, NULL, NULL, NULL, NULL, 'Chinese Language Education; 