ity-sign-mou-to-enhance-academic-and-scientific-cooperation/', '299', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.agreements (agreement_id, title, description, agreement_type, status, created_by, created_at, updated_at, agreement_code, title_ar, geographic_scope, start_date, end_date, effective_date, signing_date, auto_renew, renewal_term_months, non_renewal_notice_months, termination_notice_months, responsible_unit_id, need_justification, expected_value, objectives, focus_areas, collaboration_areas, implementation_methods, financial_commitments, financial_amount, financial_currency, financial_description, human_resources_commitments, human_resources_description, training_programs, training_programs_description, annual_report_required, monitoring_plan, confidentiality_terms, intellectual_property_terms, compliance_terms, relationship_disclaimer, amendment_terms, dispute_resolution_terms, other_terms, legal_binding_status, signing_link, source_record_id, activated_at, expired_at) OVERRIDING SYSTEM VALUE VALUES (154, 'Framework Agreement - Royal Medical Services', 'Framework Agreement between the University of Bahrain and Royal Medical Services to enhance cooperation in medical education, academic consultations, training, scientific research and exchange of expertise. Key provisions include academic consultations, specialized conferences, seminars and workshops, mutual invitations to relevant events, academic/research/development/training/cultural activities, scientific research and exchange of studies and publications, hosting faculty members in training programmes, coordination through designated contact points, annual reporting, and implementation of specific activities through separate written agreements.', 'Framework Agreement', 'ACTIVE', 1, '2026-05-10 17:02:39', '2026-07-26 16:57:20.16977', 'UOB-AGR-300', NULL, 'LOCAL', '2025-11-17', '2030-11-17', NULL, NULL, false, NULL, NULL, 6, NULL, NULL, NULL, NULL, 'Medical Education; Training; Health Sciences; Scientific Research; Professional Development', NULL, NULL, false, NULL, 'BHD', NULL, false, NULL, false,