INSERT INTO public.agreements (agreement_id, title, description, agreement_type, status, created_by, created_at, updated_at, agreement_code, title_ar, geographic_scope, start_date, end_date, effective_date, signing_date, auto_renew, renewal_term_months, non_renewal_notice_months, termination_notice_months, responsible_unit_id, need_justification, expected_value, objectives, focus_areas, collaboration_areas, implementation_methods, financial_commitments, financial_amount, financial_currency, financial_description, human_resources_commitments, human_resources_description, training_programs, training_programs_description, annual_report_required, monitoring_plan, confidentiality_terms, intellectual_property_terms, compliance_terms, relationship_disclaimer, amendment_terms, dispute_resolution_terms, other_terms, legal_binding_status, signing_link, source_record_id, activated_at, expired_at) OVERRIDING SYSTEM VALUE VALUES (155, 'Framework Agreement - Ministry of Works', 'Framework Agreement between the Ministry of Works and the University of Bahrain in scientific research to strengthen cooperation, exchange expertise, support applied knowledge in construction and infrastructure, provide mutual training opportunities, enhance joint scientific research, and enable Ministry of Works staff to participate in solving engineering problems in projects supervised by the Ministry.', 'Framework Agreement', 'ACTIVE', 1, '2026-05-10 17:02:39', '2026-07-26 16:57:20.16977', 'UOB-AGR-301', NULL, 'LOCAL', '2025-08-17', '2028-08-17', NULL, NULL, false, NULL, NULL, 6, NULL, NULL, NULL, NULL, 'Scientific Research; Infrastructure; Construction; Engineering; Training; Applied Knowledge', NULL, NULL, false, NULL, 'BHD', NULL, false, NULL, false, NULL, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'NON_BINDING', 'https://www.uob.edu.bh/wp-content/uploads/2026/04/Annual-Report-2025.pdf', '301', NULL, NULL) ON CONFLICT DO NOTHING;
