udent Training', NULL, NULL, false, NULL, 'BHD', NULL, false, NULL, false, NULL, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'NON_BINDING', 'https://www.uob.edu.bh/customs-affairs-signs-framework-agreement-with-university-of-bahrain/', '305', NULL, NULL) ON CONFLICT DO NOTHING;
