ration', NULL, NULL, false, NULL, 'BHD', NULL, false, NULL, false, NULL, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'NON_BINDING', 'https://www.uob.edu.bh/university-of-bahrain-signs-mou-with-the-gulf-petrochemicals-and-chemicals-association/', '306', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.agreements (agreement_id, title, description, agreement_type, status, created_by, created_at, updated_at, agreement_code, title_ar, geographic_scope, start_date, end_date, effective_date, signing_date, auto_renew, renewal_term_months, non_renewal_notice_months, termination_notice_months, responsible_unit_id, need_justification, expected_value, objectives, focus_areas, collaboration_areas, implementation_methods, financial_commitments, financial_amount, financial_currency, financial_description, human_resources_commitments, human_resources_description, training_programs, training_programs_description, annual_report_required, monitoring_plan, confidentiality_terms, intellectual_property_terms, compliance_terms, relationship_disclaimer, amendment_terms, dispute_resolution_terms, other_terms, legal_binding_status, signing_link, source_record_id, activated_at, expired_at) OVERRIDING SYSTEM VALUE VALUES (161, 'Small-Scale Funding Agreement - UNEP / GEF Minamata Convention Initial Assessment (MIA) for the Kingdom of Bahrain', 'Small-Scale Funding Agreement between the United Nations Environment Programme (UNEP) and the University of Bahrain as Executing Agency for the GEF Enabling Activity project: Development of Minamata Convention Initial Assessment (MIA) for the Kingdom of Bahrain. The project aims to facilitate early implementation of the Minamata Convention through scientific and technical knowledge and tools for national stakeholders in Bahrain. Key provisions include UOB project implementation duties, reporting and financial reporting to UNEP, stakeholder coordination, UNEP oversight and technical support, and use of UNEP/GEF funds for approved project activities.', 'Small-Scale Funding Agreement / SSFA', 'ACTIVE', 1, '2026-05-10 17:02:39', '2026-07-26 16:57:20.16977', 'UOB-AGR-307', NULL, 'INTERNATIONAL', '2026-05-05', '2027-07-31', NULL, NULL, false, NULL, NULL, 6, NULL, NULL, NULL, NULL, 'Environmental Governance; Minamata Convention; Chemicals and Waste; Mercury Management; Scientific and Technical Knowledge; GEF Enabling Activity; Sustainability', NULL, NULL, false, NULL, 'BHD', NULL, false, NULL, false, NULL, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'NON_BINDING', 'https://www.unep.org/gef/projects/development-minamata-convention-initial-assessment-mia-kingdom-bahrain', '307', NULL, NULL) ON CONFLICT DO NOTHING;
