owledge dissemination, research and scientific publishing, competitions and awards in humanitarian fields; organizing joint events such as conferences, seminars, lectures and training/workshops; giving priority to registering the Foundation''s sponsored children and applicants from needy families at the University of Bahrain according to applicable rules; appointing coordinators from both parties; maintaining confidentiality; and agreeing that any future financial commitments must be separately agreed.", "focus_areas": "Humanitarian Cooperation; Community Service; Research Collaboration; Knowledge Dissemination; Student Support; Conferences and Training", "other_terms": null, "partner_ids": [30], "activated_at": null, "agreement_id": 141, "partner_name": "Royal Humanitarian Foundation (RHF)", "signing_date": null, "signing_link": "https://www.uob.edu.bh/42058/", "partner_names": ["Royal Humanitarian Foundation (RHF)"], "relationships": [], "agreement_code": "UOB-AGR-286", "agreement_type": "Framework Agreement / إطار عمل", "effective_date": null, "expected_value": null, "amendment_terms": null, "monitoring_plan": null, "compliance_terms": null, "financial_amount": null, "geographic_scope": "LOCAL", "source_record_id": "286", "training_programs": false, "executive_programs": [], "financial_currency": "BHD", "need_justification": null, "collaboration_areas": null, "renewal_term_months": null, "responsible_unit_id": null, "legal_binding_status": "NON_BINDING", "confidentiality_terms": null, "financial_commitments": false, "financial_description": null, "responsible_unit_name": "Not specified", "annual_report_required": true, "implementation_methods": null, "relationship_disclaimer": null, "dispute_resolution_terms": null, "non_renewal_notice_months": null, "termination_notice_months": 6, "human_resources_commitments": false, "human_resources_description": null, "intellectual_property_terms": null, "training_programs_description": null}') ON CONFLICT DO NOTHING;
