unting and Auditing Organization for Islamic Financial Institutions (AAOIFI) to support mutual cooperation in Islamic banking and finance. Key provisions include possible UoB institutional membership in AAOIFI; joint seminars, events and workshops; public hearings and awareness activities; considering AAOIFI CIPA and CSAA programmes within BSc and MSc programmes; up to 70% discount on CIPA and CSAA fellowships for UoB faculty, alumni and students of Islamic finance; strengthening UoB Islamic finance offerings based on AAOIFI standards; participation of UoB officials in AAOIFI subcommittees, working groups and technical boards; feedback on AAOIFI exposure drafts through the Sustainable Islamic Business and Finance Research Center; information exchange; and contribution of research papers/technical articles to JOIFA.", "focus_areas": "Islamic Finance; Accounting and Auditing Standards; Professional Certification; Capacity Building; Standards Development; Research Collaboration", "other_terms": null, "partner_ids": [28], "activated_at": null, "agreement_id": 139, "partner_name": "Accounting and Auditing Organization for Islamic Financial Institutions (AAOIFI)", "signing_date": null, "signing_link": "https://www.uob.edu.bh/41494/", "partner_names": ["Accounting and Auditing Organization for Islamic Financial Institutions (AAOIFI)"], "relationships": [], "agreement_code": "UOB-AGR-284", "agreement_type": "Memorandum of Understanding / MOU", "effective_date": null, "expected_value": null, "amendment_terms": null, "monitoring_plan": null, "compliance_terms": null, "financial_amount": null, "geographic_scope": "LOCAL", "source_record_id": "284", "training_programs": false, "executive_programs": [], "financial_currency": "BHD", "need_justification": null, "collaboration_areas": null, "renewal_term_months": null, "responsible_unit_id": null, "legal_binding_status": "NON_BINDING", "confidentiality_terms": null, "financial_commitments": false, "financial_description": null, "re