INSERT INTO public.audit_logs (audit_id, table_name, record_id, action, user_id, old_data, new_data, reason, ip_address, created_at) OVERRIDING SYSTEM VALUE VALUES (153, 'agreements', 139, 'INSERT', 1, NULL, '{"sdgs": [4, 8, 16, 17], "title": "MOU - Accounting and Auditing Organization for Islamic Financial Institutions (AAOIFI)", "status": "ACTIVE", "metrics": [{"notes": "Students of Islamic finance may receive up to 70% discount on CIPA and CSAA fellowships; no number specified", "metric_code": "STUDENTS_EXCHANGED", "actual_value": null, "agreement_id": 139, "planned_value": null, "agreement_metric_id": 79}, {"notes": "UoB faculty members may receive up to 70% discount on CIPA and CSAA fellowships and support through standards-development activities; no number specified", "metric_code": "FACULTY_EXCHANGED", "actual_value": null, "agreement_id": 139, "planned_value": null, "agreement_metric_id": 80}, {"notes": "Potential inclusion of CIPA and CSAA programmes into BSc and MSc programmes; no joint degree specified", "metric_code": "JOINT_PROGRAMS", "actual_value": null, "agreement_id": 139, "planned_value": null, "agreement_metric_id": 81}], "contacts": [], "end_date": "2027-04-27", "partners": [{"city": "Seef, Manama", "country": "Bahrain", "website": "https://aaoifi.com/?lang=en", "latitude": "26.235000", "logo_url": "https://aaoifi.com/?lang=en", "longitude": "50.534000", "partner_id": 28, "partner_type": "International Standard-Setting Organization / Not-for-Profit Organization", "organization_name": "Accounting and Auditing Organization for Islamic Financial Institutions (AAOIFI)"}], "rankings": ["QS_WORLD"], "title_ar": null, "auto_renew": false, "created_at": "2026-05-10 17:02:39", "created_by": 1, "expired_at": null, "objectives": null, "partner_id": 28, "start_date": "2024-04-28", "updated_at": "2026-07-26 16:57:20.16977", "description": "MOU between the University of Bahrain and the Accounting and Auditing Organization for Islamic Financial Institutions (AAOIFI) to support mutual cooperation in Islamic banking and finance. Key provisions include possible UoB institutional membership in AAOIFI; joint seminars, events and workshops; public hearings and awareness activities; considering AAOIFI CIPA and CSAA programmes within BSc and MSc programmes; up to 70% discount on CIPA and CSAA fellowships for UoB faculty, alumni and students of Islamic finance; strengthening UoB Islamic finance offerings based on AAOIFI standards; participation of UoB officials in AAOIFI subcommittees, working groups and technical boards; feedback on AAOIFI exposure drafts through the Sustainable Islamic Business and Finance Research Center; information exchange; and contribution of research papers/technical articles to JOIFA.", "focus_areas": "Islamic Finance; Accounting and Auditing Standards; Professional Certification; Capacity Building; Standards Development; Research Collaboration", "other_terms": null, "partner_ids": [28], "activated_at": null, "agreement_id": 139, "partner_name": "Accounting and Auditing Organization for Islamic Financial Institutions (AAOIFI)", "signing_date": null, "signing_link": "https://www.uob.edu.bh/41494/", "partner_names": ["Accounting and Auditing Organization for Islamic Financial Institutions (AAOIFI)"], "relationships": [], "agreement_code": "UOB-AGR-284", "agreement_type": "Memorandum of Understanding / MOU", "effective_date": null, "expected_value": null, "amendment_terms": null, "monitoring_plan": null, "compliance_terms": null, "financial_amount": null, "geographic_scope": "LOCAL", "source_record_id": "284", "training_programs": false, "executive_programs": [], "financial_currency": "BHD", "need_justification": null, "collaboration_areas": null, "renewal_term_months": null, "responsible_unit_id": null, "legal_binding_status": "NON_BINDING", "confidentiality_terms": null, "financial_commitments": false, "financial_description": null, "responsible_unit_name": "College of Business Administration", "annual_rep