ies such as online workshops, toolkits, webinars and newsletters; opportunities to participate in GPCA awards and initiatives; in-person industry awareness workshops for STEM students; cooperation in academic and research programmes including sustainability, capability building and community outreach; and a kick-off meeting to agree roles and responsibilities.", "focus_areas": "Petrochemicals; Chemicals Industry; Sustainability; STEM Awareness; Capability Building; Industry Collaboration", "other_terms": null, "partner_ids": [50], "activated_at": null, "agreement_id": 160, "partner_name": "Gulf Petrochemicals and Chemicals Association (GPCA)", "signing_date": null, "signing_link": "https://www.uob.edu.bh/university-of-bahrain-signs-mou-with-the-gulf-petrochemicals-and-chemicals-association/", "partner_names": ["Gulf Petrochemicals and Chemicals Association (GPCA)"], "relationships": [], "agreement_code": "UOB-AGR-306", "agreement_type": "Memorandum of Understanding / MOU", "effective_date": null, "expected_value": null, "amendment_terms": null, "monitoring_plan": null, "compliance_terms": null, "financial_amount": null, "geographic_scope": "LOCAL", "source_record_id": "306", "training_programs": false, "executive_programs": [], "financial_currency": "BHD", "need_justification": null, "collaboration_areas": null, "renewal_term_months": null, "responsible_unit_id": null, "legal_binding_status": "NON_BINDING", "confidentiality_terms": null, "financial_commitments": false, "financial_description": null, "responsible_unit_name": "College of Engineering", "annual_report_required": true, "implementation_methods": null, "relationship_disclaimer": null, "dispute_resolution_terms": null, "non_renewal_notice_months": null, "termination_notice_months": 6, "human_resources_commitments": false, "human_resources_description": null, "intellectual_property_terms": null, "training_programs_description": null}', 'Controlled legacy CSV import from agreements.csv row 41', NULL, '2026-07