ledge and tools for national stakeholders in Bahrain. Key provisions include UOB project implementation duties, reporting and financial reporting to UNEP, stakeholder coordination, UNEP oversight and technical support, and use of UNEP/GEF funds for approved project activities.", "focus_areas": "Environmental Governance; Minamata Convention; Chemicals and Waste; Mercury Management; Scientific and Technical Knowledge; GEF Enabling Activity; Sustainability", "other_terms": null, "partner_ids": [51], "activated_at": null, "agreement_id": 161, "partner_name": "United Nations Environment Programme (UNEP)", "signing_date": null, "signing_link": "https://www.unep.org/gef/projects/development-minamata-convention-initial-assessment-mia-kingdom-bahrain", "partner_names": ["United Nations Environment Programme (UNEP)"], "relationships": [], "agreement_code": "UOB-AGR-307", "agreement_type": "Small-Scale Funding Agreement / SSFA", "effective_date": null, "expected_value": null, "amendment_terms": null, "monitoring_plan": null, "compliance_terms": null, "financial_amount": null, "geographic_scope": "INTERNATIONAL", "source_record_id": "307", "training_programs": false, "executive_programs": [], "financial_currency": "BHD", "need_justification": null, "collaboration_areas": null, "renewal_term_months": null, "responsible_unit_id": null, "legal_binding_status": "NON_BINDING", "confidentiality_terms": null, "financial_commitments": false, "financial_description": null, "responsible_unit_name": "College of Engineering", "annual_report_required": true, "implementation_methods": null, "relationship_disclaimer": null, "dispute_resolution_terms": null, "non_renewal_notice_months": null, "termination_notice_months": 6, "human_resources_commitments": false, "human_resources_description": null, "intellectual_property_terms": null, "training_programs_description": null}', 'Controlled legacy CSV import from agreements.csv row 42', NULL, '2026-07-26 16:57:20.16977') ON CONFLICT DO NOTHING;
